(287,'D4270','PERIODONTIC','pedicle soft tissue graft procedure','Not a covered benefit','None','None'),
(288,'D4273','PERIODONTIC','autogenous connective tissue graft procedure (including donor and recipient surgical sites) first tooth, implant, or edentulous tooth position in graft','Not a covered benefit','None','None'),
(289,'D4274','PERIODONTIC','mesial/distal wedge procedure, single tooth (when not performed in conjunction with surgical procedures in the same anatomical area)','Not a covered benefit','None','None'),
